CREATE SCHEMA IF NOT EXISTS "pedidos";
CREATE TABLE IF NOT EXISTS "pedidos"."reservas" ("id" UUID PRIMARY KEY, "tenantId" UUID NOT NULL, "produtorId" UUID NOT NULL, "eventoId" UUID NOT NULL, "loteId" UUID NOT NULL, "quantidade" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'ATIVA', "expiraEm" TIMESTAMPTZ NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS "pedidos"."pedidos" ("id" UUID PRIMARY KEY, "numero" TEXT UNIQUE NOT NULL, "tenantId" UUID NOT NULL, "produtorId" UUID NOT NULL, "eventoId" UUID NOT NULL, "reservaId" UUID, "compradorNome" TEXT NOT NULL, "compradorDocumento" TEXT, "compradorEmail" TEXT, "compradorTelefone" TEXT, "status" TEXT NOT NULL DEFAULT 'AGUARDANDO_PAGAMENTO', "subtotal" DECIMAL(14,2) NOT NULL, "taxaDisk" DECIMAL(14,2) NOT NULL, "total" DECIMAL(14,2) NOT NULL, "repasseProdutor" DECIMAL(14,2) NOT NULL, "modeloTaxaSnapshot" TEXT NOT NULL, "taxaPercentualSnapshot" DECIMAL(5,2), "taxaFixaSnapshot" DECIMAL(14,2), "spreadSnapshot" DECIMAL(5,2), "advancedSnapshot" BOOLEAN NOT NULL DEFAULT FALSE, "prazoRepasseSnapshot" INTEGER NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "paidAt" TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS "pedidos"."itens_pedido" ("id" UUID PRIMARY KEY, "pedidoId" UUID NOT NULL, "loteId" UUID NOT NULL, "quantidade" INTEGER NOT NULL, "valorUnitario" DECIMAL(14,2) NOT NULL, "subtotal" DECIMAL(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS "pedidos"."pagamentos" ("id" UUID PRIMARY KEY, "pedidoId" UUID NOT NULL, "tenantId" UUID NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDENTE', "metodo" TEXT NOT NULL, "adquirente" TEXT, "transacaoId" TEXT, "nsu" TEXT, "valor" DECIMAL(14,2) NOT NULL, "pagoEm" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS "pedidos"."ingressos" ("id" UUID PRIMARY KEY, "numero" TEXT UNIQUE NOT NULL, "pedidoId" UUID NOT NULL, "eventoId" UUID NOT NULL, "loteId" UUID NOT NULL, "status" TEXT NOT NULL DEFAULT 'VALIDO', "qrTokenHash" TEXT UNIQUE NOT NULL, "emitidoEm" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "utilizadoEm" TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS "pedidos_evento_idx" ON "pedidos"."pedidos" ("tenantId","eventoId","createdAt");
CREATE INDEX IF NOT EXISTS "ingressos_evento_idx" ON "pedidos"."ingressos" ("eventoId","status");
